// Catalogue for the static site. Loads samples.json (generated by
// scripts/build-site-data.js), renders filterable cards, and shows one
// sample's setup, scopes, and full Code.gs on click. No network calls
// beyond samples.json, and no code is executed here.
(function () {
  const searchEl = document.getElementById('search');
  const serviceEl = document.getElementById('service');
  const difficultyEl = document.getElementById('difficulty');
  const cardsEl = document.getElementById('cards');
  const countEl = document.getElementById('count');
  const detailEl = document.getElementById('detail');
  let samples = [];

  function escapeHtml(text) {
    return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function filtered() {
    const query = searchEl.value.trim().toLowerCase();
    return samples.filter((sample) => {
      const haystack = [sample.title, sample.description, sample.services.join(' ')].join(' ').toLowerCase();
      return (!query || haystack.includes(query)) &&
        (!serviceEl.value || sample.services.includes(serviceEl.value)) &&
        (!difficultyEl.value || sample.difficulty === difficultyEl.value);
    });
  }

  function renderCards() {
    const list = filtered();
    countEl.textContent = list.length + ' sample' + (list.length === 1 ? '' : 's');
    cardsEl.innerHTML = '';
    list.forEach((sample) => {
      const button = document.createElement('button');
      button.className = 'card';
      button.innerHTML = '<h2>' + escapeHtml(sample.title) + '</h2>' +
        '<p>' + escapeHtml(sample.description) + '</p>' +
        '<p>' + sample.services.map((s) => '<span class="tag">' + escapeHtml(s) + '</span>').join('') +
        '<span class="tag">' + escapeHtml(sample.difficulty) + '</span></p>';
      button.addEventListener('click', () => renderDetail(sample));
      cardsEl.appendChild(button);
    });
    if (list.length === 0) {
      cardsEl.textContent = 'No samples match those filters.';
    }
  }

  function renderDetail(sample) {
    detailEl.hidden = false;
    detailEl.innerHTML = '<h2>' + escapeHtml(sample.title) + '</h2>' +
      '<p>' + escapeHtml(sample.description) + '</p>' +
      '<h3>Setup</h3><ol>' + sample.setup.map((step) => '<li>' + escapeHtml(step) + '</li>').join('') + '</ol>' +
      '<h3>OAuth scopes</h3><ul>' + sample.scopes.map((scope) => '<li><code>' + escapeHtml(scope) + '</code></li>').join('') + '</ul>' +
      '<h3>Code.gs</h3><pre><code>' + escapeHtml(sample.code) + '</code></pre>' +
      '<p>Files: <code>samples/' + escapeHtml(sample.slug) + '/Code.gs</code> and ' +
      '<code>samples/' + escapeHtml(sample.slug) + '/appsscript.json</code></p>';
    detailEl.scrollIntoView();
  }

  fetch('samples.json').then((res) => res.json()).then((data) => {
    samples = data;
    const services = [...new Set(samples.flatMap((s) => s.services))].sort();
    services.forEach((service) => {
      const option = document.createElement('option');
      option.textContent = service;
      serviceEl.appendChild(option);
    });
    [searchEl, serviceEl, difficultyEl].forEach((el) => el.addEventListener('input', renderCards));
    renderCards();
  }).catch(() => {
    cardsEl.textContent = 'Could not load samples.json. Run npm run build:site first.';
  });
})();
